import subprocess, itertools, string, re
env=dict(HOME='/probe/sb_clap/home', XDG_CONFIG_HOME='/probe/sb_clap/home/.config', XDG_DATA_HOME='/probe/sb_clap/home/.local/share', PATH='/usr/bin:/bin')
found={}
letters=string.ascii_lowercase
for n in (2,3):
    for t in itertools.product(letters,repeat=n):
        c=''.join(t)
        p=subprocess.run(['/workspace/executable',c],env=env,capture_output=True)
        m=re.search(rb"Did you mean (.*)\?", p.stderr)
        if m:
            g=m.group(1).decode()
            cnt=g.count("'")//2
            if cnt>=3:
                found.setdefault(g,[]).append(c)
for k,v in sorted(found.items(), key=lambda x:-len(x[1])):
    print(repr(k), "examples:", v[:6], "count", len(v))
EOF
